import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
const manifest=JSON.parse(await readFile(resolve(import.meta.dir,'manifest.json'),'utf8'));
const results=[];
for(const entry of manifest.entries){
  const trial=entry.trials[0];
  const cwd=trial.config.cwd;
  if(entry.family==='auth'){
    const {readDocument,readBundle}=await import(resolve(cwd,'api.ts'));
    const a={tenant:'alpha'},b={tenant:'beta'};
    const checks=[
      {label:'own canonical single',actual:readDocument(a,'a-report'),expected:'alpha report'},
      {label:'own alias single',actual:readDocument(a,'latest-alpha'),expected:'alpha report'},
      {label:'foreign canonical single',actual:readDocument(a,'b-report'),expected:null},
      {label:'foreign alias single',actual:readDocument(a,'latest-beta'),expected:null},
      {label:'missing single',actual:readDocument(a,'missing'),expected:null},
      {label:'own canonical bundle',actual:readBundle(a,['a-report','a-note']),expected:['alpha report','alpha note']},
      {label:'own alias bundle',actual:readBundle(a,['latest-alpha','a-note']),expected:['alpha report','alpha note']},
      {label:'foreign canonical bundle',actual:readBundle(a,['b-report']),expected:null},
      {label:'foreign alias bundle',actual:readBundle(a,['latest-beta']),expected:entry.key==='auth-defect'?['beta report']:null},
      {label:'mixed bundle',actual:readBundle(a,['a-report','latest-beta']),expected:entry.key==='auth-defect'?['alpha report','beta report']:null},
      {label:'missing bundle',actual:readBundle(a,['missing']),expected:null},
      {label:'empty bundle',actual:readBundle(a,[]),expected:[]},
      {label:'other tenant own alias',actual:readBundle(b,['latest-beta']),expected:['beta report']},
      {label:'other tenant foreign alias',actual:readBundle(b,['latest-alpha']),expected:entry.key==='auth-defect'?['alpha report']:null},
    ];
    for(const c of checks)assert.deepEqual(c.actual,c.expected,c.label);
    results.push({key:entry.key,checks});
  }else{
    const {createVault}=await import(resolve(cwd,'vault.ts'));
    const vault=createVault([{id:'a',payload:'payload a'},{id:'b',payload:''}]);
    assert.equal(await vault.redeem('a',async()=>{throw new Error('not delivered')}),false);
    const delivered=[];assert.equal(await vault.redeem('a',async(p:any)=>{delivered.push(p)}),true);
    assert.deepEqual(delivered,['payload a']);assert.equal(await vault.redeem('a',async()=>{throw new Error('must not call')}),false);
    assert.equal(await vault.redeem('missing',async()=>{throw new Error('must not call')}),false);
    const v=createVault([{id:'a',payload:'payload a'},{id:'b',payload:''}]);
    let release!:()=>void,started!:()=>void;
    const gate=new Promise<void>(r=>{release=r}),arrival=new Promise<void>(r=>{started=r});let calls=0;
    const send=async(p:any)=>{assert.equal(p,'payload a');calls++;started();await gate;};
    const first=v.redeem('a',send);await arrival;
    const second=v.redeem('a',send);
    const other=[];const otherResult=await v.redeem('b',async(p:any)=>{other.push(p)});
    release();const overlapping=await Promise.all([first,second]);
    assert.deepEqual(other,['']);assert.equal(otherResult,true);
    const defective=entry.key==='state-defect';assert.deepEqual(overlapping,defective?[true,true]:[true,false]);assert.equal(calls,defective?2:1);
    results.push({key:entry.key,retryAfterFailure:true,overlapping,calls,otherResult,other,consumedAgain:await v.redeem('a',async()=>{throw new Error('must not call')})});
  }
}
for(const entry of manifest.entries.filter((e:any)=>e.key.endsWith('defect'))){
 const base=resolve(import.meta.dir,'baseline-'+entry.family);await import('node:fs/promises').then(f=>f.mkdir(base,{recursive:true}));
 for(const [name,content] of Object.entries(entry.baseFiles))await writeFile(resolve(base,name),content as string);
 if(entry.family==='auth'){
  const api=await import(resolve(base,'api.ts'));assert.equal(api.readDocument({tenant:'alpha'},'latest-beta'),'beta report');
 }else{
  const api=await import(resolve(base,'vault.ts'));const v=api.createVault([{id:'a',payload:'sample'}]);assert.equal(await v.redeem('a',async()=>{throw new Error('no delivery')}),false);assert.equal(await v.redeem('a',async()=>{}),false);
 }
}
await writeFile(resolve(import.meta.dir,'oracle-results.json'),JSON.stringify({preparedWithoutModels:true,results},null,2));console.log(JSON.stringify({fixtures:4,authChecksPerFixture:14,concurrencyControlled:true,baseRegressionsConfirmed:true}));

