export type Document = { id: string; tenant: string; body: string };
const documents = new Map<string, Document>([
  ['a-report', { id: 'a-report', tenant: 'alpha', body: 'alpha report' }],
  ['a-note', { id: 'a-note', tenant: 'alpha', body: 'alpha note' }],
  ['b-report', { id: 'b-report', tenant: 'beta', body: 'beta report' }],
]);
const aliases = new Map([['latest-alpha', 'a-report'], ['latest-beta', 'b-report']]);
export function resolveDocument(requestedId: string): Document | null {
  return documents.get(aliases.get(requestedId) ?? requestedId) ?? null;
}
export function isCanonicalId(requestedId: string): boolean {
  return documents.has(requestedId);
}

