import { isCanonicalId, resolveDocument, type Document } from './catalog';
export type Context = { tenant: string };
export function canRead(context: Context, document: Document): boolean {
  return context.tenant === document.tenant;
}
export function requestedIdsAllowed(context: Context, ids: readonly string[]): boolean {
  return ids.filter(isCanonicalId).every(id => {
    const document = resolveDocument(id);
    return document !== null && canRead(context, document);
  });
}

