import { resolveDocument } from './catalog';
import { requestedIdsAllowed, type Context } from './access';
export function readDocument(context: Context, requestedId: string): string | null {
  if (!requestedIdsAllowed(context, [requestedId])) return null;
  return resolveDocument(requestedId)?.body ?? null;
}
export function readBundle(context: Context, requestedIds: readonly string[]): string[] | null {
  if (!requestedIdsAllowed(context, requestedIds)) return null;
  const documents = requestedIds.map(resolveDocument);
  if (documents.some(document => document === null)) return null;
  return documents.map(document => document!.body);
}

