export type Grant = { id: string; payload: string };
export type Deliver = (payload: string) => Promise<void>;
export function createVault(seed: readonly Grant[]) {
  const grants = new Map(seed.map(grant => [grant.id, grant.payload]));
  return {
    async redeem(id: string, deliver: Deliver): Promise<boolean> {
      const payload = grants.get(id);
      if (payload === undefined) return false;
      grants.delete(id);
      try { await deliver(payload); return true; } catch { return false; }
    },
  };
}

