export type Grant = { id: string; payload: string };
export type Deliver = (payload: string) => Promise<void>;
export function createVault(seed: readonly Grant[]) {
  const grants = new Map(seed.map(grant => [grant.id, { payload: grant.payload, pending: false }]));
  return {
    async redeem(id: string, deliver: Deliver): Promise<boolean> {
      const grant = grants.get(id);
      if (grant === undefined || grant.pending) return false;
      grant.pending = true;
      try {
        await deliver(grant.payload);
        grants.delete(id);
        return true;
      } catch {
        grant.pending = false;
        return false;
      }
    },
  };
}

